// --- Per-L dispatch ---
inline constexpr std::size_t n_cart_for_l(int L) noexcept {
    return static_cast<std::size_t>((L + 1) * (L + 2) / 2);
}
inline constexpr std::size_t n_sph_for_l(int L) noexcept {
    return static_cast<std::size_t>(2 * L + 1);
}

inline const double* sph_table_for_l(int L) noexcept {
    switch (L) {
        case 0: return kSph0.data();
        case 1: return kSph1.data();
        case 2: return kSph2.data();
        case 3: return kSph3.data();
        case 4: return kSph4.data();
        case 5: return kSph5.data();
        case 6: return kSph6.data();
        default: return nullptr;
    }
}

inline const CartIdx* cart_table_for_l(int L) noexcept {
    switch (L) {
        case 0: return kCart0.data();
        case 1: return kCart1.data();
        case 2: return kCart2.data();
        case 3: return kCart3.data();
        case 4: return kCart4.data();
        case 5: return kCart5.data();
        case 6: return kCart6.data();
        default: return nullptr;
    }
}

